const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, HeadingLevel, BorderStyle, WidthType, ShadingType,
  LevelFormat, PageNumber, Header, Footer, TabStopType, TabStopPosition,
  VerticalAlign, PageBreak
} = require('docx');
const fs = require('fs');

// ─── BRAND COLORS ───────────────────────────────────────────────────
const GOLD       = "B8965A";
const DARK_BG    = "1A1A2E";
const MID_BG     = "2C2C4A";
const LIGHT_GOLD = "F5E6CC";
const CREAM      = "FDF8F2";
const WHITE      = "FFFFFF";
const DARK_TEXT  = "1A1A2E";
const MID_TEXT   = "4A4A6A";
const GOLD_BORDER = { style: BorderStyle.SINGLE, size: 12, color: GOLD };
const NO_BORDER   = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
const noBorders   = { top: NO_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER };
const goldBorderBottom = { top: NO_BORDER, bottom: GOLD_BORDER, left: NO_BORDER, right: NO_BORDER };

function spacer(size = 160) {
  return new Paragraph({ spacing: { before: 0, after: size }, children: [] });
}

function goldRule() {
  return new Paragraph({
    spacing: { before: 80, after: 80 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD } },
    children: []
  });
}

// ════════════════════════════════════════════════════════════════════
//  DOC 1: What We Do For MedSpas
// ════════════════════════════════════════════════════════════════════

function buildDoc1() {
  const cellPad = { top: 100, bottom: 100, left: 140, right: 140 };
  const cellPadLg = { top: 160, bottom: 160, left: 200, right: 200 };

  // Header bar — dark background row
  function headerBanner() {
    return new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [
        new TableRow({
          children: [
            new TableCell({
              shading: { fill: DARK_BG, type: ShadingType.CLEAR },
              borders: noBorders,
              margins: { top: 360, bottom: 360, left: 400, right: 400 },
              children: [
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  children: [
                    new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, font: "Arial", size: 36, color: GOLD }),
                  ]
                }),
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  spacing: { before: 80 },
                  children: [
                    new TextRun({ text: "theluxoracollective.co", font: "Arial", size: 18, color: LIGHT_GOLD }),
                  ]
                }),
              ]
            })
          ]
        })
      ]
    });
  }

  // Headline block
  function headlineBlock() {
    return [
      spacer(200),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({ text: "We Install Revenue Systems Inside Independent MedSpas", bold: true, font: "Arial", size: 40, color: DARK_TEXT }),
        ]
      }),
      spacer(80),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [
          new TextRun({ text: "The 90-Day Growth Engine: A Done-With-You Program That Builds Memberships, Packages, and Retention Systems Your Team Runs.", font: "Arial", size: 22, color: MID_TEXT, italics: true }),
        ]
      }),
      spacer(120),
      goldRule(),
      spacer(160),
    ];
  }

  // 3-column "What We Install" table
  function whatWeInstall() {
    const items = [
      { title: "Membership Programs", body: "Recurring revenue architecture that converts one-time clients into loyal, paying members every month." },
      { title: "Package + Upsell Frameworks", body: "Strategic bundling and at-checkout upsell scripts that increase average ticket on every visit." },
      { title: "AI-Powered Follow-Up", body: "Automated sequences that re-engage cold leads, recover no-shows, and reactivate lapsed clients." },
      { title: "Staff Sales Training", body: "Hands-on scripts and role plays so your front desk and injectors close with confidence, not pressure." },
      { title: "Marketing Execution", body: "Meta ad strategy, organic content direction, and funnel builds aligned to your growth targets." },
      { title: "Reputation Engine", body: "A systematic review and referral program that makes word-of-mouth a reliable revenue channel." },
    ];

    const rows = [];
    for (let i = 0; i < items.length; i += 3) {
      const group = items.slice(i, i + 3);
      while (group.length < 3) group.push({ title: "", body: "" });
      rows.push(
        new TableRow({
          children: group.map(item =>
            new TableCell({
              shading: { fill: item.title ? CREAM : WHITE, type: ShadingType.CLEAR },
              borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
              margins: cellPad,
              width: { size: 3120, type: WidthType.DXA },
              children: item.title ? [
                new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: item.title, bold: true, font: "Arial", size: 20, color: GOLD })] }),
                new Paragraph({ children: [new TextRun({ text: item.body, font: "Arial", size: 18, color: DARK_TEXT })] }),
              ] : [new Paragraph({ children: [] })]
            })
          )
        })
      );
      // gap row
      rows.push(new TableRow({
        children: [new TableCell({ borders: noBorders, margins: { top: 60, bottom: 60 }, width: { size: 9360, type: WidthType.DXA }, columnSpan: 3, children: [new Paragraph({ children: [] })] })]
      }));
    }

    return [
      new Paragraph({ children: [new TextRun({ text: "What We Install Inside Your Medspa", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(120),
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
      spacer(200),
    ];
  }

  // The 90-Day Roadmap
  function roadmapSection() {
    const phases = [
      { phase: "Days 1-30", label: "Revenue Foundation", color: DARK_BG, items: ["Membership program launch", "Package + upsell architecture", "LTV sales training", "AI follow-up activation"] },
      { phase: "Days 31-60", label: "Growth Amplification", color: MID_BG, items: ["Partnership framework", "Reputation Engine build-out", "Meta ad strategy", "Referral program launch"] },
      { phase: "Days 61-90", label: "Scale and Celebrate", color: "3A3A5A", items: ["90-Day Celebration Event", "Retention system review", "KPI scorecard delivery", "Roadmap to Year 2"] },
    ];

    const rows = [
      new TableRow({
        children: phases.map(p =>
          new TableCell({
            shading: { fill: p.color, type: ShadingType.CLEAR },
            borders: noBorders,
            margins: cellPadLg,
            width: { size: 3120, type: WidthType.DXA },
            children: [
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: p.phase, bold: true, font: "Arial", size: 18, color: GOLD })] }),
              new Paragraph({ spacing: { after: 100 }, children: [new TextRun({ text: p.label, bold: true, font: "Arial", size: 22, color: WHITE })] }),
              ...p.items.map(item =>
                new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: "\u2714  " + item, font: "Arial", size: 18, color: LIGHT_GOLD })] })
              )
            ]
          })
        )
      })
    ];

    return [
      new Paragraph({ children: [new TextRun({ text: "The 90-Day Growth Engine Roadmap", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(120),
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
      spacer(200),
    ];
  }

  // Who We Serve
  function whoWeServe() {
    return [
      goldRule(),
      spacer(140),
      new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Who We Serve", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(100),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "We partner exclusively with independent medspa owners generating $500K to $3M annually who are ready to install sustainable revenue systems and stop trading time for transactions.", font: "Arial", size: 20, color: MID_TEXT })]
      }),
      spacer(160),
    ];
  }

  // Results bar
  function resultsBar() {
    const stats = [
      { num: "90", label: "Days to a Full Revenue System" },
      { num: "3x", label: "Average Membership Revenue Lift" },
      { num: "100%", label: "Done-With-You Implementation" },
    ];
    const rows = [
      new TableRow({
        children: stats.map(s =>
          new TableCell({
            shading: { fill: LIGHT_GOLD, type: ShadingType.CLEAR },
            borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
            margins: { top: 160, bottom: 160, left: 120, right: 120 },
            width: { size: 3120, type: WidthType.DXA },
            children: [
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: s.num, bold: true, font: "Arial", size: 52, color: GOLD })] }),
              new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: s.label, font: "Arial", size: 18, color: DARK_TEXT })] }),
            ]
          })
        )
      })
    ];
    return [
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
      spacer(200),
    ];
  }

  // CTA footer
  function ctaFooter() {
    return [
      goldRule(),
      spacer(140),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Ready to Install the Growth Engine?", bold: true, font: "Arial", size: 28, color: DARK_TEXT })]
      }),
      spacer(80),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Book your Competitive Intelligence Briefing at theluxoracollective.co", font: "Arial", size: 20, color: MID_TEXT })]
      }),
      spacer(60),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", bold: true, font: "Arial", size: 20, color: GOLD })]
      }),
    ];
  }

  const allChildren = [
    headerBanner(),
    ...headlineBlock(),
    ...whatWeInstall(),
    ...roadmapSection(),
    ...whoWeServe(),
    ...resultsBar(),
    ...ctaFooter(),
  ];

  return new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 22 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: allChildren
    }]
  });
}

// ════════════════════════════════════════════════════════════════════
//  DOC 2: Partner + Affiliate One-Pager
// ════════════════════════════════════════════════════════════════════

function buildDoc2() {
  const cellPad = { top: 100, bottom: 100, left: 140, right: 140 };
  const cellPadLg = { top: 160, bottom: 160, left: 200, right: 200 };

  function headerBanner() {
    return new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [
        new TableRow({
          children: [
            new TableCell({
              shading: { fill: DARK_BG, type: ShadingType.CLEAR },
              borders: noBorders,
              margins: { top: 360, bottom: 360, left: 400, right: 400 },
              children: [
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, font: "Arial", size: 36, color: GOLD })]
                }),
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  spacing: { before: 80 },
                  children: [new TextRun({ text: "Strategic Partner + Affiliate Program", font: "Arial", size: 24, color: LIGHT_GOLD, bold: true })]
                }),
                new Paragraph({
                  alignment: AlignmentType.CENTER,
                  spacing: { before: 60 },
                  children: [new TextRun({ text: "theluxoracollective.co", font: "Arial", size: 18, color: LIGHT_GOLD })]
                }),
              ]
            })
          ]
        })
      ]
    });
  }

  function openingBlock() {
    return [
      spacer(200),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "Your Brand, Embedded in Every Medspa We Grow.", bold: true, font: "Arial", size: 38, color: DARK_TEXT })]
      }),
      spacer(80),
      new Paragraph({
        alignment: AlignmentType.CENTER,
        children: [new TextRun({ text: "We are the growth partner for independent medspas generating $500K to $3M annually. When you partner with The Luxora Collective, your products and services become our go-to recommendation inside every client engagement, every playbook, and every training we deliver.", font: "Arial", size: 20, color: MID_TEXT })]
      }),
      spacer(120),
      goldRule(),
      spacer(160),
    ];
  }

  // Who We Work With (partner types)
  function partnerTypes() {
    const types = [
      "Stem Cell Therapy Providers",
      "Peptide + Hormone Replacement Therapy",
      "Luxury Skincare Lines",
      "Medical-Grade Product Distributors",
      "Interior Design + Medspa Buildout",
      "Practice Management Software",
      "Aesthetic Equipment + Technology",
      "Wellness and IV Therapy Brands",
      "Financial + Financing Partners",
      "EMR / GHL / Tech Platforms",
      "Photography + Content Studios",
      "Staffing + Recruiting Agencies",
    ];

    const half = Math.ceil(types.length / 2);
    const col1 = types.slice(0, half);
    const col2 = types.slice(half);
    while (col2.length < col1.length) col2.push("");

    const rows = col1.map((item, i) =>
      new TableRow({
        children: [col1[i], col2[i]].map(text =>
          new TableCell({
            shading: { fill: text ? CREAM : WHITE, type: ShadingType.CLEAR },
            borders: { top: NO_BORDER, bottom: { style: BorderStyle.SINGLE, size: 1, color: "E0D5C5" }, left: NO_BORDER, right: NO_BORDER },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: 4680, type: WidthType.DXA },
            children: text ? [
              new Paragraph({ children: [new TextRun({ text: "\u2714  " + text, font: "Arial", size: 19, color: DARK_TEXT })] })
            ] : [new Paragraph({ children: [] })]
          })
        )
      })
    );

    return [
      new Paragraph({ children: [new TextRun({ text: "Who This Is Built For", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(80),
      new Paragraph({ children: [new TextRun({ text: "We partner with any brand that serves the medspa owner's business or their clients' wellness journey, including:", font: "Arial", size: 20, color: MID_TEXT })] }),
      spacer(120),
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
      spacer(200),
    ];
  }

  // 3 Tiers
  function tierSection() {
    const tiers = [
      {
        tier: "TIER 1",
        name: "Affiliate Partner",
        color: "2C2C4A",
        items: [
          "Custom affiliate link + tracking dashboard",
          "Named recommendation in client-facing playbooks",
          "Listed in Luxora Preferred Vendor Directory",
          "Monthly performance reporting",
          "Revenue share on referred client purchases",
        ]
      },
      {
        tier: "TIER 2",
        name: "Embedded Partner",
        color: DARK_BG,
        items: [
          "All Tier 1 benefits included",
          "Co-branded content and case studies",
          "Featured in our client onboarding resources",
          "Priority recommendation in relevant playbook modules",
          "Quarterly strategy alignment call",
          "Intro to our active client roster (warm referral)",
        ]
      },
      {
        tier: "TIER 3",
        name: "Strategic Alliance",
        color: "0D0D1F",
        items: [
          "All Tier 1 and Tier 2 benefits included",
          "White-label integration inside 90-Day deliverables",
          "Exclusive category lock (no competing brands recommended)",
          "Joint webinar and event opportunities",
          "Cross-promotion to Luxora Community (medspa owners)",
          "Custom training module co-developed for our clients",
          "Named anchor partner in all marketing materials",
        ]
      },
    ];

    const rows = [
      new TableRow({
        children: tiers.map(t =>
          new TableCell({
            shading: { fill: t.color, type: ShadingType.CLEAR },
            borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
            margins: cellPadLg,
            width: { size: 3120, type: WidthType.DXA },
            children: [
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: t.tier, bold: true, font: "Arial", size: 16, color: GOLD })] }),
              new Paragraph({ spacing: { after: 120 }, children: [new TextRun({ text: t.name, bold: true, font: "Arial", size: 24, color: WHITE })] }),
              ...t.items.map(item =>
                new Paragraph({ spacing: { after: 80 }, children: [new TextRun({ text: "\u2022  " + item, font: "Arial", size: 17, color: LIGHT_GOLD })] })
              )
            ]
          })
        )
      })
    ];

    return [
      new Paragraph({ children: [new TextRun({ text: "Partnership Tiers", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(80),
      new Paragraph({ children: [new TextRun({ text: "Choose the integration level that fits your goals. All tiers are built around one outcome: making your brand the default recommendation inside our client base.", font: "Arial", size: 20, color: MID_TEXT })] }),
      spacer(120),
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
      spacer(200),
    ];
  }

  // Why Partner With Us
  function whyUs() {
    const reasons = [
      { icon: "01", title: "Direct Access to Buyers", body: "Our clients are medspa owners actively investing in their businesses. They are not browsing. They are buying." },
      { icon: "02", title: "Trusted Recommendation Layer", body: "We are not a marketplace. We recommend a short list of vetted partners. Your brand gets the weight of a trusted advisor endorsement, not an ad." },
      { icon: "03", title: "Done-With-You Integration", body: "We embed your products and services directly into our implementation work. Clients experience your brand as part of the solution, not an upsell." },
      { icon: "04", title: "Growing Client Roster", body: "Our medspa client base expands monthly. Every new client we onboard is a new warm introduction to your brand." },
    ];

    const half = 2;
    const rows = [
      new TableRow({
        children: reasons.slice(0, 2).map(r =>
          new TableCell({
            shading: { fill: CREAM, type: ShadingType.CLEAR },
            borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
            margins: cellPad,
            width: { size: 4680, type: WidthType.DXA },
            children: [
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: r.icon, bold: true, font: "Arial", size: 28, color: GOLD })] }),
              new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: r.title, bold: true, font: "Arial", size: 20, color: DARK_TEXT })] }),
              new Paragraph({ children: [new TextRun({ text: r.body, font: "Arial", size: 18, color: MID_TEXT })] }),
            ]
          })
        )
      }),
      new TableRow({
        children: [new TableCell({ borders: noBorders, margins: { top: 80, bottom: 0 }, columnSpan: 2, width: { size: 9360, type: WidthType.DXA }, children: [new Paragraph({ children: [] })] })]
      }),
      new TableRow({
        children: reasons.slice(2, 4).map(r =>
          new TableCell({
            shading: { fill: CREAM, type: ShadingType.CLEAR },
            borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
            margins: cellPad,
            width: { size: 4680, type: WidthType.DXA },
            children: [
              new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: r.icon, bold: true, font: "Arial", size: 28, color: GOLD })] }),
              new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: r.title, bold: true, font: "Arial", size: 20, color: DARK_TEXT })] }),
              new Paragraph({ children: [new TextRun({ text: r.body, font: "Arial", size: 18, color: MID_TEXT })] }),
            ]
          })
        )
      }),
    ];

    return [
      new Paragraph({ children: [new TextRun({ text: "Why Partner With The Luxora Collective", bold: true, font: "Arial", size: 26, color: DARK_TEXT })] }),
      spacer(120),
      new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
      spacer(200),
    ];
  }

  // CTA
  function ctaFooter() {
    return [
      new Table({
        width: { size: 9360, type: WidthType.DXA },
        columnWidths: [9360],
        rows: [
          new TableRow({
            children: [
              new TableCell({
                shading: { fill: DARK_BG, type: ShadingType.CLEAR },
                borders: noBorders,
                margins: { top: 300, bottom: 300, left: 400, right: 400 },
                children: [
                  new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: "Let's Build This Together.", bold: true, font: "Arial", size: 32, color: WHITE })] }),
                  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 80 }, children: [new TextRun({ text: "Reach out to explore which tier is the right fit for your brand.", font: "Arial", size: 20, color: LIGHT_GOLD })] }),
                  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 100 }, children: [new TextRun({ text: "theluxoracollective.co", bold: true, font: "Arial", size: 22, color: GOLD })] }),
                  new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 60 }, children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", font: "Arial", size: 18, color: LIGHT_GOLD })] }),
                ]
              })
            ]
          })
        ]
      }),
    ];
  }

  const allChildren = [
    headerBanner(),
    ...openingBlock(),
    ...partnerTypes(),
    ...tierSection(),
    ...whyUs(),
    ...ctaFooter(),
  ];

  return new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 22 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: allChildren
    }]
  });
}

// ─── WRITE BOTH ─────────────────────────────────────────────────────
async function main() {
  const doc1 = buildDoc1();
  const buf1 = await Packer.toBuffer(doc1);
  fs.writeFileSync("/home/claude/luxora_medspa_what_we_do.docx", buf1);
  console.log("Doc 1 written.");

  const doc2 = buildDoc2();
  const buf2 = await Packer.toBuffer(doc2);
  fs.writeFileSync("/home/claude/luxora_partner_affiliate.docx", buf2);
  console.log("Doc 2 written.");
}

main().catch(console.error);

