const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType,
} = require('docx');
const fs = require('fs');

const GOLD        = "B8965A";
const DARK_BG     = "1A1A2E";
const MID_BG      = "2C2C4A";
const DEEP_BG     = "0D0D1F";
const LIGHT_GOLD  = "F5E6CC";
const CREAM       = "FDF8F2";
const WHITE       = "FFFFFF";
const DARK_TEXT   = "1A1A2E";
const MID_TEXT    = "4A4A6A";

const GOLD_BORDER = { style: BorderStyle.SINGLE, size: 12, color: GOLD };
const THIN_BORDER = { style: BorderStyle.SINGLE, size: 1,  color: "E0D5C5" };
const NO_BORDER   = { style: BorderStyle.NONE,   size: 0,  color: "FFFFFF" };
const noBorders   = { top: NO_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER };

const sp = (n = 120) => new Paragraph({ spacing: { before: 0, after: n }, children: [] });

const goldRule = () => new Paragraph({
  spacing: { before: 80, after: 80 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD } },
  children: []
});

function sectionLabel(text) {
  return new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 16, bold: true, color: GOLD, allCaps: true })]
  });
}

function bodyText(text, italic = false) {
  return new Paragraph({
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 19, color: MID_TEXT, italics: italic })]
  });
}

// ── HEADER BANNER ────────────────────────────────────────────────────

function headerBanner() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        shading: { fill: DARK_BG, type: ShadingType.CLEAR },
        borders: noBorders,
        margins: { top: 380, bottom: 380, left: 440, right: 440 },
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, font: "Arial", size: 40, color: GOLD })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 80 },
            children: [new TextRun({ text: "Partnership & Collaboration Overview", font: "Arial", size: 22, color: LIGHT_GOLD, bold: true })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 60 },
            children: [new TextRun({ text: "Building the Aesthetic Industry Ecosystem Together", font: "Arial", size: 18, color: LIGHT_GOLD, italics: true })]
          }),
        ]
      })]
    })]
  });
}

// ── WHO WE ARE ───────────────────────────────────────────────────────

function whoWeAre() {
  return [
    sp(200),
    sectionLabel("Who We Are"),
    goldRule(),
    sp(100),
    bodyText(
      "The Luxora Collective is a premium growth partner for independent med spa owners who are ready to stop leaving money on the table and start running a business that actually performs at the level they built it for. We are not a traditional consulting firm, and we are not an agency selling ad spend. We are a revenue systems partner — and the distinction matters."
    ),
    bodyText(
      "We begin every engagement with a Revenue Leak Audit: a deep-dive diagnostic that identifies exactly where a med spa is losing money right now, before recommending a single new service, piece of equipment, or dollar of additional ad spend. Most owners are sitting on tens of thousands in untapped revenue inside their existing client base, their front desk interactions, their booking process, and their follow-up systems. We find it, and we help them capture it."
    ),
    bodyText(
      "From there, we install proven revenue systems across memberships, package architecture, staff sales training, AI-powered client follow-up, CRM integration, retention frameworks, and lifetime value optimization. Our clients are not buying strategy documents. They are implementing systems that compound over time and produce predictable, sustainable revenue without adding overhead, buying more lasers, or scaling ad budgets before the foundation is solid."
    ),
    bodyText(
      "We sit at the center of the med spa ecosystem. We know what these owners need, what they will actually use, and what moves the needle. That position makes us one of the most valuable partnership channels available to any brand that serves this space."
    ),
    sp(160),
  ];
}

// ── WHY PARTNER ──────────────────────────────────────────────────────

function whyPartner() {
  const points = [
    { num: "01", title: "Direct Access to Active Buyers", body: "Our clients are medspa owners already invested in growth. They are not browsing. They are implementing, purchasing, and executing with budget allocated and intention behind every decision." },
    { num: "02", title: "Trusted Advisor Endorsement", body: "We recommend a curated short list of partners. Your brand carries the weight of a trusted referral from an advisor already inside the owner's business, not a cold ad or a directory listing." },
    { num: "03", title: "Embedded in Every Engagement", body: "Your products and services are woven directly into our implementation work. Clients experience your brand as part of the solution they are already committed to, not an upsell added later." },
    { num: "04", title: "A Growing, Qualified Roster", body: "Our client base expands every month. Every new medspa we onboard is a warm, pre-qualified introduction to your brand from a partner they already trust." },
  ];

  const rows = [
    new TableRow({
      children: points.slice(0, 2).map(p => new TableCell({
        shading: { fill: CREAM, type: ShadingType.CLEAR },
        borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 4680, type: WidthType.DXA },
        children: [
          new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: p.num, bold: true, font: "Arial", size: 26, color: GOLD })] }),
          new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: p.title, bold: true, font: "Arial", size: 20, color: DARK_TEXT })] }),
          new Paragraph({ children: [new TextRun({ text: p.body, font: "Arial", size: 18, color: MID_TEXT })] }),
        ]
      }))
    }),
    new TableRow({
      children: [new TableCell({ borders: noBorders, margins: { top: 60, bottom: 0 }, columnSpan: 2, width: { size: 9360, type: WidthType.DXA }, children: [sp(40)] })]
    }),
    new TableRow({
      children: points.slice(2, 4).map(p => new TableCell({
        shading: { fill: CREAM, type: ShadingType.CLEAR },
        borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
        margins: { top: 120, bottom: 120, left: 160, right: 160 },
        width: { size: 4680, type: WidthType.DXA },
        children: [
          new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: p.num, bold: true, font: "Arial", size: 26, color: GOLD })] }),
          new Paragraph({ spacing: { after: 60 }, children: [new TextRun({ text: p.title, bold: true, font: "Arial", size: 20, color: DARK_TEXT })] }),
          new Paragraph({ children: [new TextRun({ text: p.body, font: "Arial", size: 18, color: MID_TEXT })] }),
        ]
      }))
    }),
  ];

  return [
    sectionLabel("Why Partner With Us"),
    goldRule(),
    sp(100),
    bodyText("Partnering with The Luxora Collective means direct access to a curated network of growth-focused med spa owners who are actively investing in their businesses. These are not passive leads. They are owners already committed to change, already writing checks, and already looking for exactly what you offer."),
    sp(100),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
    sp(200),
  ];
}

// ── WHAT WE OFFER PARTNERS ───────────────────────────────────────────

function whatWeOfferTiers() {
  const tiers = [
    {
      tier: "TIER 1",
      name: "Affiliate Partner",
      color: MID_BG,
      items: [
        "Custom affiliate link + tracking dashboard",
        "Named recommendation in client-facing playbooks",
        "Luxora Preferred Vendor Directory listing",
        "Monthly performance reporting",
        "Revenue share on all referred client purchases",
        "Feature in Luxora partner spotlight content",
      ]
    },
    {
      tier: "TIER 2",
      name: "Embedded Partner",
      color: DARK_BG,
      items: [
        "All Tier 1 benefits included",
        "Co-branded content and case studies",
        "Featured across client onboarding resources",
        "Priority recommendation in relevant playbook modules",
        "Guest feature on The Luxora Collective podcast",
        "Dedicated page on The Luxora Collective website",
        "Quarterly strategy alignment call",
        "Warm introductions to our active client roster",
      ]
    },
    {
      tier: "TIER 3",
      name: "Strategic Alliance",
      color: DEEP_BG,
      items: [
        "All Tier 1 and Tier 2 benefits included",
        "White-label integration inside 90-Day client deliverables",
        "Exclusive category lock — no competing brands recommended",
        "Named anchor partner in all Luxora marketing",
        "Joint webinar and live event opportunities",
        "Cross-promotion to the full Luxora medspa owner community",
        "Custom training module co-developed for our clients",
        "Recurring podcast feature and long-form content series",
        "Premium placement on Luxora website with full brand showcase",
        "Direct input into how your brand is positioned to our clients",
      ]
    },
  ];

  const rows = [new TableRow({
    children: tiers.map(t => new TableCell({
      shading: { fill: t.color, type: ShadingType.CLEAR },
      borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
      margins: { top: 160, bottom: 160, left: 180, right: 180 },
      width: { size: 3120, type: WidthType.DXA },
      children: [
        new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: t.tier, bold: true, font: "Arial", size: 16, color: GOLD })] }),
        new Paragraph({ spacing: { after: 120 }, children: [new TextRun({ text: t.name, bold: true, font: "Arial", size: 22, color: WHITE })] }),
        ...t.items.map(item =>
          new Paragraph({ spacing: { after: 72 }, children: [new TextRun({ text: "\u2022  " + item, font: "Arial", size: 17, color: LIGHT_GOLD })] })
        )
      ]
    }))
  })];

  return [
    sectionLabel("What We Offer Our Partners"),
    goldRule(),
    sp(100),
    bodyText("Every tier is built around one outcome: making your brand the default recommendation inside our growing medspa client base. Choose the level of integration that fits your goals."),
    sp(100),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
    sp(200),
  ];
}

// ── WHAT WE'RE LOOKING FOR IN EXCHANGE ──────────────────────────────

function whatWeAskSection() {
  const tiers = [
    {
      tier: "TIER 1",
      name: "Referral Revenue Share",
      color: MID_BG,
      intro: "For affiliate-level partners, we ask for a straightforward referral arrangement:",
      items: [
        "A defined commission or revenue share on every client we send your way",
        "Trackable referral link or dedicated promo code for attribution",
        "Timely reporting so we can confirm conversion and compensation",
        "A competitive offer for our client base — our referrals reflect on us",
      ]
    },
    {
      tier: "TIER 2",
      name: "Preferred Growth Partner Status",
      color: DARK_BG,
      intro: "For embedded partners, we are asking for a deeper seat at the table:",
      items: [
        "Formal designation as a Preferred Luxora Growth Partner",
        "Warm introduction to your existing medspa client base as the go-to growth partner recommendation",
        "Co-marketing commitment — shared audiences, shared reach",
        "A referral revenue share on clients you send to The Luxora Collective",
        "Collaborative content and visibility across your owned channels",
        "Commitment to a quarterly alignment call to keep the partnership active",
      ]
    },
    {
      tier: "TIER 3",
      name: "Full Strategic Integration",
      color: DEEP_BG,
      intro: "For Strategic Alliance partners, we are building something that benefits both audiences at scale:",
      items: [
        "Exclusive category positioning — we promote no competing brands",
        "White-label rights for Luxora-branded content inside your client-facing materials",
        "Access to The Luxora Collective as a named growth resource for your medspa clients",
        "Joint product or program development opportunities",
        "Revenue share structure on all mutual client conversions, in both directions",
        "Active co-promotion across all channels — email, podcast, social, and events",
        "Annual strategic planning session to align roadmaps and maximize shared impact",
        "First right of refusal on new Luxora program categories and expansion opportunities",
      ]
    },
  ];

  const rows = [new TableRow({
    children: tiers.map(t => new TableCell({
      shading: { fill: t.color, type: ShadingType.CLEAR },
      borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
      margins: { top: 160, bottom: 160, left: 180, right: 180 },
      width: { size: 3120, type: WidthType.DXA },
      children: [
        new Paragraph({ spacing: { after: 40 }, children: [new TextRun({ text: t.tier, bold: true, font: "Arial", size: 16, color: GOLD })] }),
        new Paragraph({ spacing: { after: 100 }, children: [new TextRun({ text: t.name, bold: true, font: "Arial", size: 20, color: WHITE })] }),
        new Paragraph({ spacing: { after: 100 }, children: [new TextRun({ text: t.intro, font: "Arial", size: 17, color: LIGHT_GOLD, italics: true })] }),
        ...t.items.map(item =>
          new Paragraph({ spacing: { after: 72 }, children: [new TextRun({ text: "\u2022  " + item, font: "Arial", size: 17, color: LIGHT_GOLD })] })
        )
      ]
    }))
  })];

  return [
    sectionLabel("What We Are Looking For in Exchange"),
    goldRule(),
    sp(100),
    bodyText("Every great partnership is a two-way street. We bring our client relationships, our trust equity, and our platform. Here is what we ask in return, scaled to the level of integration we are building together."),
    sp(100),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [3120, 3120, 3120], rows }),
    sp(200),
  ];
}

// ── WHO WE'RE LOOKING FOR ────────────────────────────────────────────

function whoWeLookFor() {
  const categories = [
    "Clinical treatment and therapy providers",
    "Aesthetic and wellness product brands",
    "Medical-grade and professional skincare lines",
    "Technology, software, and practice platforms",
    "Equipment, devices, and treatment tools",
    "Financial, lending, and payment solutions",
    "Education, certification, and training programs",
    "Facility design and environment specialists",
    "Marketing, media, and creative services",
    "Any brand that serves the aesthetic industry",
  ];

  const half = Math.ceil(categories.length / 2);
  const col1 = categories.slice(0, half);
  const col2 = categories.slice(half);
  while (col2.length < col1.length) col2.push("");

  const rows = col1.map((item, i) =>
    new TableRow({
      children: [col1[i], col2[i]].map(text =>
        new TableCell({
          shading: { fill: text ? CREAM : WHITE, type: ShadingType.CLEAR },
          borders: { top: NO_BORDER, bottom: THIN_BORDER, left: NO_BORDER, right: NO_BORDER },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          width: { size: 4680, type: WidthType.DXA },
          children: text
            ? [new Paragraph({ children: [new TextRun({ text: "\u2714  " + text, font: "Arial", size: 19, color: DARK_TEXT })] })]
            : [new Paragraph({ children: [] })]
        })
      )
    })
  );

  return [
    sectionLabel("Who We Are Looking For"),
    goldRule(),
    sp(100),
    bodyText("We are actively seeking partners across every corner of the aesthetic industry. If your brand serves the medspa environment, its owners, or the clients who walk through those doors, we want to talk."),
    sp(80),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
    sp(200),
  ];
}

// ── CTA FOOTER ───────────────────────────────────────────────────────

function ctaFooter() {
  return [
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [new TableRow({
        children: [new TableCell({
          shading: { fill: DARK_BG, type: ShadingType.CLEAR },
          borders: noBorders,
          margins: { top: 300, bottom: 300, left: 440, right: 440 },
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Let's Start the Conversation.", bold: true, font: "Arial", size: 30, color: WHITE })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Every partnership begins with a simple discovery call. No commitment, just a conversation about what a collaboration could look like and how we can create real value for each other's clients.", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 120 },
              children: [new TextRun({ text: "www.theluxoracollective.co   |   partnerships@theluxoracollective.co", bold: true, font: "Arial", size: 20, color: GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
          ]
        })]
      })]
    }),
    sp(80),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "Confidential — For Prospective Partner Review Only", font: "Arial", size: 16, color: MID_TEXT, italics: true })]
    }),
  ];
}

// ── ASSEMBLE + WRITE ─────────────────────────────────────────────────

async function main() {
  const doc = new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 20 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: [
        headerBanner(),
        ...whoWeAre(),
        ...whyPartner(),
        ...whatWeOfferTiers(),
        ...whatWeAskSection(),
        ...whoWeLookFor(),
        ...ctaFooter(),
      ]
    }]
  });

  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync("/home/claude/luxora_partnership_overview_v2.docx", buf);
  console.log("Done.");
}

main().catch(console.error);

