    sp(200),
  ];
}

// ── WHO WE'RE LOOKING FOR ────────────────────────────────────────────

function whoWeLookFor() {
  const categories = [
    "Clinical treatment and therapy providers",
    "Aesthetic and wellness product brands",
    "Medical-grade and professional skincare lines",
    "Technology, software, and practice platforms",
    "Equipment, devices, and treatment tools",
    "Financial, lending, and payment solutions",
    "Education, certification, and training programs",
    "Facility design and environment specialists",
    "Marketing, media, and creative services",
    "Any brand that serves the aesthetic industry",
  ];

  const half = Math.ceil(categories.length / 2);
  const col1 = categories.slice(0, half);
  const col2 = categories.slice(half);
  while (col2.length < col1.length) col2.push("");

  const rows = col1.map((item, i) =>
    new TableRow({
      children: [col1[i], col2[i]].map(text =>
        new TableCell({
          shading: { fill: text ? CREAM : WHITE, type: ShadingType.CLEAR },
          borders: { top: NO_BORDER, bottom: THIN_BORDER, left: NO_BORDER, right: NO_BORDER },
          margins: { top: 80, bottom: 80, left: 120, right: 120 },
          width: { size: 4680, type: WidthType.DXA },
          children: text
            ? [new Paragraph({ children: [new TextRun({ text: "\u2714  " + text, font: "Arial", size: 19, color: DARK_TEXT })] })]
            : [new Paragraph({ children: [] })]
        })
      )
    })
  );

  return [
    sectionLabel("Who We Are Looking For"),
    goldRule(),
    sp(100),
    bodyText("We are actively seeking partners across every corner of the aesthetic industry. If your brand serves the medspa environment, its owners, or the clients who walk through those doors, we want to talk."),
    sp(80),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
    sp(200),
  ];
}

// ── CTA FOOTER ───────────────────────────────────────────────────────

function ctaFooter() {
  return [
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [new TableRow({
        children: [new TableCell({
          shading: { fill: DARK_BG, type: ShadingType.CLEAR },
          borders: noBorders,
          margins: { top: 300, bottom: 300, left: 440, right: 440 },
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Let's Start the Conversation.", bold: true, font: "Arial", size: 30, color: WHITE })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Every partnership begins with a simple discovery call. No commitment, just a conversation about what a collaboration could look like and how we can create real value for each other's clients.", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 120 },
              children: [new TextRun({ text: "www.theluxoracollective.co   |   partnerships@theluxoracollective.co", bold: true, font: "Arial", size: 20, color: GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
          ]
        })]
      })]
    }),
    sp(80),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "Confidential — For Prospective Partner Review Only", font: "Arial", size: 16, color: MID_TEXT, italics: true })]
    }),
  ];
}

// ── ASSEMBLE + WRITE ─────────────────────────────────────────────────

async function main() {
  const doc = new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 20 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: [
        headerBanner(),
        ...whoWeAre(),
        ...whyPartner(),
        ...whatWeOfferTiers(),
        ...whatWeAskSection(),
        ...whoWeLookFor(),
        ...ctaFooter(),
      ]
    }]
  });

  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync("/home/claude/luxora_partnership_overview_v2.docx", buf);
  console.log("Done.");
}

main().catch(console.error);
