                        children: [new TextRun({ text: "What We Would Love in Return", bold: true, font: "Arial", size: 17, color: GOLD })]
                      }),
                    ]
                  }),
                ]
              }),
              // content row
              new TableRow({
                children: [
                  new TableCell({
                    borders: noBorders,
                    margins: { top: 40, bottom: 0, left: 0, right: 60 },
                    width: { size: 4460, type: WidthType.DXA },
                    children: leftItems
                  }),
                  new TableCell({
                    borders: noBorders,
                    margins: { top: 40, bottom: 0, left: 60, right: 0 },
                    width: { size: 4460, type: WidthType.DXA },
                    children: rightItems
                  }),
                ]
              }),
              // ideal for row
              new TableRow({
                children: [
                  new TableCell({
                    borders: { top: THIN_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
                    margins: { top: 100, bottom: 0, left: 0, right: 0 },
                    columnSpan: 2,
                    width: { size: 8920, type: WidthType.DXA },
                    children: [
                      new Paragraph({
                        children: [
                          new TextRun({ text: "Best suited for: ", bold: true, font: "Arial", size: 17, color: GOLD }),
                          new TextRun({ text: idealFor, font: "Arial", size: 17, color: LIGHT_GOLD, italics: true }),
                        ]
                      })
                    ]
                  })
                ]
              }),
            ]
          }),
        ]
      })
    ]
  });

  return [
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [9360], rows: [outerRow] }),
    sp(160),
  ];
}

// ── THREE TIERS ───────────────────────────────────────────────────────

function allTiers() {
  const t1 = tierBlock(
    "TIER 1",
    "Affiliate Partner",
    "A simple, low-commitment starting point that still creates real value on both sides.",
    MID_BG,
    [
      "Your brand recommended by name inside our client playbooks and training materials",
      "Listed in the Luxora Preferred Vendor Directory, visible to our full client base",
      "A trackable referral link so our clients can access your offer directly",
      "Spotlight feature in Luxora partner content, introducing your brand to our audience",
      "Monthly reporting so you can see the volume and quality of referrals coming your way",
    ],
    [
      "A referral commission or revenue share on purchases made by clients we send your way",
      "A dedicated offer or promo code for the Luxora client base",
      "An agreement that our referrals are handled with the same care we extend to them",
      "Open communication if something is not converting so we can adjust together",
    ],
    "Brands newer to the medspa space, or those wanting to test the relationship before going deeper."
  );

  const t2 = tierBlock(
    "TIER 2",
    "Embedded Partner",
    "For brands ready to be genuinely woven into how we serve our clients, not just mentioned.",
    DARK_BG,
    [
      "Priority recommendation inside the specific playbook modules where your brand is most relevant",
      "A dedicated page on The Luxora Collective website showcasing your brand and offer",
      "A guest feature on The Luxora Collective podcast, where you speak directly to our audience",
      "Co-branded content and case studies we develop and distribute together",
      "Warm introductions to our active client roster as a vetted, trusted resource",
      "Inclusion in our client onboarding experience so new clients know about you from day one",
      "A quarterly call to review what is working, adjust positioning, and plan ahead",
    ],
    [
      "Recognition of The Luxora Collective as a Preferred Growth Partner in your client-facing materials",
      "Warm introductions to your existing medspa clients as a recommended growth resource",
      "Shared visibility across your owned channels, email, social, or content, in whatever form fits",
      "A referral fee or revenue share on any medspa owner you send our way who becomes a client",
      "A genuine commitment to the partnership, not a set-it-and-forget-it arrangement",
    ],
    "Established brands with an existing medspa client base who want to grow it together with us."
  );

  const t3 = tierBlock(
    "TIER 3",
    "Growth Ecosystem Partner",
    "For brands where the vision goes beyond referrals and into something that shapes both businesses.",
    DEEP_BG,
    [
      "White-label integration of your brand inside Luxora's 90-Day client deliverables",
      "Named presence across all Luxora marketing as a foundational ecosystem partner",
      "Recurring podcast features and long-form content that builds your authority with our audience",
      "Premium placement on The Luxora Collective website with a full brand showcase",
      "Joint webinars, live events, or workshops co-hosted for our respective communities",
      "Cross-promotion to the full Luxora medspa owner community across all channels",
      "A custom training module or resource co-developed specifically for our shared clients",
      "Early access to new Luxora programs, categories, and expansion opportunities",
      "An annual strategy session to align on where both businesses are headed",
    ],
    [
      "Access to The Luxora Collective as a named, embedded growth resource for your medspa clients",
      "White-label rights to use Luxora-branded frameworks inside your own client materials",
      "A mutual revenue share on client conversions flowing in both directions",
      "Active co-promotion across your channels at a level that matches the depth of the partnership",
      "Collaborative input on joint offerings, content, or experiences we build together",
      "A long-term mindset: we are building something that compounds, not a one-season campaign",
    ],
    "Brands that are deeply embedded in the medspa world and want a true ecosystem-level relationship."
  );

  return [...t1, ...t2, ...t3];
}

// ── CUSTOM CLOSE ─────────────────────────────────────────────────────

function customClose() {
  return [
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [new TableRow({
        children: [new TableCell({
          shading: { fill: DARK_BG, type: ShadingType.CLEAR },
          borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
          margins: { top: 300, bottom: 300, left: 440, right: 440 },
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "None of These Fit Perfectly? Good.", bold: true, font: "Arial", size: 28, color: WHITE })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 100 },
              children: [new TextRun({ text: "The best partnerships we have built did not come from a pre-set structure. They came from a conversation where both sides were honest about what they needed and creative about how to get there. If you see pieces of two tiers that make sense, or something entirely different, bring it to the table. We are flexible, we are collaborative, and we are genuinely interested in figuring out what a partnership between our companies could look like at its best.", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 140 },
              children: [new TextRun({ text: "www.theluxoracollective.co   |   partnerships@theluxoracollective.co", bold: true, font: "Arial", size: 20, color: GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
          ]
        })]
      })]
    }),
    sp(80),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "Confidential — For Prospective Partner Review Only", font: "Arial", size: 16, color: MID_TEXT, italics: true })]
    }),
  ];
}

// ── ASSEMBLE ─────────────────────────────────────────────────────────

async function main() {
  const doc = new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 20 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: [
        headerBanner(),
        ...opening(),
        ...allTiers(),
        ...customClose(),
      ]
    }]
  });

  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync("/home/claude/luxora_partnership_tiers_vision.docx", buf);
  console.log("Done.");
}

main().catch(console.error);
