const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType,
} = require('docx');
const fs = require('fs');

const GOLD        = "B8965A";
const DARK_BG     = "1A1A2E";
const MID_BG      = "2C2C4A";
const DEEP_BG     = "0D0D1F";
const LIGHT_GOLD  = "F5E6CC";
const CREAM       = "FDF8F2";
const WHITE       = "FFFFFF";
const DARK_TEXT   = "1A1A2E";
const MID_TEXT    = "4A4A6A";

const GOLD_BORDER = { style: BorderStyle.SINGLE, size: 12, color: GOLD };
const SOFT_BORDER = { style: BorderStyle.SINGLE, size: 4,  color: GOLD };
const THIN_BORDER = { style: BorderStyle.SINGLE, size: 1,  color: "E0D5C5" };
const NO_BORDER   = { style: BorderStyle.NONE,   size: 0,  color: "FFFFFF" };
const noBorders   = { top: NO_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER };

const sp = (n = 120) => new Paragraph({ spacing: { before: 0, after: n }, children: [] });

const goldRule = () => new Paragraph({
  spacing: { before: 80, after: 80 },
  border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: GOLD } },
  children: []
});

function sectionLabel(text) {
  return new Paragraph({
    spacing: { before: 0, after: 60 },
    children: [new TextRun({ text, font: "Arial", size: 16, bold: true, color: GOLD, allCaps: true })]
  });
}

function bodyText(text, italic = false) {
  return new Paragraph({
    spacing: { before: 0, after: 80 },
    children: [new TextRun({ text, font: "Arial", size: 19, color: MID_TEXT, italics: italic })]
  });
}

function boldBodyText(label, text) {
  return new Paragraph({
    spacing: { before: 0, after: 80 },
    children: [
      new TextRun({ text: label + " ", font: "Arial", size: 19, color: DARK_TEXT, bold: true }),
      new TextRun({ text, font: "Arial", size: 19, color: MID_TEXT }),
    ]
  });
}

// ── HEADER ───────────────────────────────────────────────────────────

function headerBanner() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        shading: { fill: DARK_BG, type: ShadingType.CLEAR },
        borders: noBorders,
        margins: { top: 360, bottom: 360, left: 440, right: 440 },
        children: [
          new Paragraph({
            alignment: AlignmentType.CENTER,
            children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, font: "Arial", size: 36, color: GOLD })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 60 },
            children: [new TextRun({ text: "x", font: "Arial", size: 22, color: LIGHT_GOLD })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 60 },
            children: [new TextRun({ text: "BEAM WELLNESS", bold: true, font: "Arial", size: 36, color: LIGHT_GOLD })]
          }),
          new Paragraph({
            alignment: AlignmentType.CENTER,
            spacing: { before: 80 },
            children: [new TextRun({ text: "A Custom Partnership Vision", font: "Arial", size: 20, color: LIGHT_GOLD, italics: true })]
          }),
        ]
      })]
    })]
  });
}

// ── WHY THIS MAKES SENSE ─────────────────────────────────────────────

function whyThisMakesSense() {
  return [
    sp(200),
    sectionLabel("Why This Makes Sense"),
    goldRule(),
    sp(100),
    bodyText(
      "From the moment we connected, the overlap was obvious. Beam Wellness is already inside the aesthetic and wellness world, working with the exact owners we serve every day. You understand what these women need, you know how to position red light as a treatment experience rather than a gadget add-on, and your brand is built around results and relationships rather than just product movement."
    ),
    bodyText(
      "The Luxora Collective works from the inside out. We go into med spas and build revenue systems around what they already have before recommending anything new. That means when red light comes up, and it comes up often, we are not pitching it cold. We are presenting it as a natural extension of a treatment experience the owner is already building. That is a very different conversation, and it is one where Beam Wellness fits seamlessly."
    ),
    bodyText(
      "There is also a genuine values alignment here. You care about the owner's success, not just a placement. We care about the same thing. That is not as common as it should be, and it matters to us.", true
    ),
    sp(160),
  ];
}

// ── WHERE WE SEE THE FIT ─────────────────────────────────────────────

function whereWeSeeTheFit() {
  const fits = [
    {
      title: "Inside Our Playbooks",
      body: "We deliver eight comprehensive playbooks across every 90-day engagement. Red light therapy is a natural fit inside our package architecture, membership add-on, and retail integration modules. We would name Beam Wellness specifically as our recommended provider, not a generic category mention."
    },
    {
      title: "As a Retail and Revenue Add-On",
      body: "We teach every client how to build a retail revenue stream that does not feel pushy or transactional. Beam products sitting at the front desk or in a retail display, tied to a client education conversation, is exactly the kind of low-lift high-impact revenue we train for."
    },
    {
      title: "Inside Membership and Package Builds",
      body: "One of the most compelling membership and package structures we build is the experience add-on: a complimentary treatment layer that increases perceived value without increasing provider time. Red light as a built-in session enhancement is a perfect example of this done right."
    },
    {
      title: "For IV, Cryo, and Wellness Crossover Clients",
      body: "A significant portion of our client base either already offers or is actively considering adding IV therapy, cryotherapy, or recovery-focused services. Red light is a natural bridge between aesthetic and wellness, and we already speak that language with our clients."
    },
    {
      title: "As a Staff Training Touchpoint",
      body: "We train front desk teams and providers on how to have consultative conversations that lead to upgrades and add-ons without pressure. Beam's education materials and product knowledge translate directly into those scripts."
    },
  ];

  const rows = fits.map(f =>
    new TableRow({
      children: [
        new TableCell({
          shading: { fill: CREAM, type: ShadingType.CLEAR },
          borders: { top: THIN_BORDER, bottom: NO_BORDER, left: GOLD_BORDER, right: NO_BORDER },
          margins: { top: 100, bottom: 100, left: 180, right: 180 },
          width: { size: 2200, type: WidthType.DXA },
          children: [
            new Paragraph({
              children: [new TextRun({ text: f.title, bold: true, font: "Arial", size: 18, color: DARK_TEXT })]
            })
          ]
        }),
        new TableCell({
          borders: { top: THIN_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
          margins: { top: 100, bottom: 100, left: 180, right: 60 },
          width: { size: 7160, type: WidthType.DXA },
          children: [
            new Paragraph({
              children: [new TextRun({ text: f.body, font: "Arial", size: 18, color: MID_TEXT })]
            })
          ]
        }),
      ]
    })
  );

  return [
    sectionLabel("Where We See the Fit"),
    goldRule(),
    sp(100),
    bodyText("These are not hypotheticals. These are real moments inside our existing client engagements where Beam Wellness belongs in the conversation."),
    sp(100),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [2200, 7160], rows }),
    sp(200),
  ];
}

// ── WHAT THIS COULD LOOK LIKE ────────────────────────────────────────

function whatThisCouldLookLike() {
  const cols = [
    {
      label: "What We Could Bring to Beam",
      color: MID_BG,
      items: [
        "Named recommendation inside Luxora playbooks delivered to every new client",
        "A dedicated partner page on The Luxora Collective website showcasing Beam Wellness",
        "A feature on The Luxora Collective podcast to speak directly to our medspa owner audience",
        "Warm introductions to our active client roster as a vetted, trusted product partner",
        "Staff training integration so Luxora clients know how to present and sell Beam products with confidence",
        "Co-branded content built around red light as a revenue and retention tool inside the medspa",
        "Ongoing recommendation in our bi-weekly client calls whenever the opportunity is relevant",
      ]
    },
    {
      label: "What We Would Love in Return",
      color: DARK_BG,
      items: [
        "Beam Wellness recognizing The Luxora Collective as a recommended growth partner for your medspa clients",
        "Warm introductions to your existing medspa partners who could benefit from our 90-day program",
        "Access to Beam's education materials, fact sheets, and product training resources for our client playbooks",
        "A referral commission or revenue share on purchases made by Luxora clients through your platform",
        "A referral fee on any medspa client you introduce to us who becomes a Luxora client",
        "Shared visibility across Beam's owned channels when relevant and organic",
        "A standing quarterly check-in to keep the partnership alive and evolving together",
      ]
    },
  ];

  const rows = [new TableRow({
    children: cols.map(c => new TableCell({
      shading: { fill: c.color, type: ShadingType.CLEAR },
      borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
      margins: { top: 180, bottom: 180, left: 200, right: 200 },
      width: { size: 4680, type: WidthType.DXA },
      children: [
        new Paragraph({
          spacing: { after: 120 },
          children: [new TextRun({ text: c.label, bold: true, font: "Arial", size: 20, color: GOLD })]
        }),
        ...c.items.map(item =>
          new Paragraph({
            spacing: { after: 80 },
            children: [new TextRun({ text: "\u2022  " + item, font: "Arial", size: 17, color: LIGHT_GOLD })]
          })
        )
      ]
    }))
  })];

  return [
    sectionLabel("What This Could Look Like"),
    goldRule(),
    sp(100),
    bodyText("These are starting points, not requirements. We are highly flexible and genuinely open to building something that works for both brands. If pieces of this feel right and others do not, bring it to the conversation and we will figure it out together."),
    sp(100),
    new Table({ width: { size: 9360, type: WidthType.DXA }, columnWidths: [4680, 4680], rows }),
    sp(200),
  ];
}

// ── THE BIGGER PICTURE ────────────────────────────────────────────────

function biggerPicture() {
  return [
    sectionLabel("The Bigger Picture"),
    goldRule(),
    sp(100),
    bodyText(
      "The aesthetic and wellness industry is converging. Med spas are adding cryo, IV therapy, peptides, and recovery modalities. Wellness centers are adding injectables and skin services. The lines are blurring fast, and the owners who win are the ones building a full-circle client experience rather than a single-service menu."
    ),
    bodyText(
      "Beam Wellness and The Luxora Collective are both operating at that intersection. You are helping owners add a modality that serves the whole client. We are helping owners build a business that retains that client for years. Together, we are not just selling them something. We are helping them build something."
    ),
    bodyText(
      "That is the kind of partnership we are most interested in, and we think it is the kind Beam Wellness is most interested in too.", true
    ),
    sp(160),
  ];
}

// ── CTA ───────────────────────────────────────────────────────────────

function ctaFooter() {
  return [
    new Table({
      width: { size: 9360, type: WidthType.DXA },
      columnWidths: [9360],
      rows: [new TableRow({
        children: [new TableCell({
          shading: { fill: DARK_BG, type: ShadingType.CLEAR },
          borders: { top: GOLD_BORDER, bottom: NO_BORDER, left: NO_BORDER, right: NO_BORDER },
          margins: { top: 300, bottom: 300, left: 440, right: 440 },
          children: [
            new Paragraph({
              alignment: AlignmentType.CENTER,
              children: [new TextRun({ text: "Let's Build This Together.", bold: true, font: "Arial", size: 30, color: WHITE })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 100 },
              children: [new TextRun({ text: "This document is a conversation starter. None of it is set in stone, and all of it is open to shaping together. We would love to get back on a call, bring Eric and Gina in, and figure out exactly what the right structure looks like for both of us.", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 140 },
              children: [new TextRun({ text: "www.theluxoracollective.co   |   partnerships@theluxoracollective.co", bold: true, font: "Arial", size: 20, color: GOLD })]
            }),
            new Paragraph({
              alignment: AlignmentType.CENTER,
              spacing: { before: 80 },
              children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO, The Luxora Collective", font: "Arial", size: 18, color: LIGHT_GOLD })]
            }),
          ]
        })]
      })]
    }),
    sp(80),
    new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "Confidential — Prepared exclusively for Beam Wellness", font: "Arial", size: 16, color: MID_TEXT, italics: true })]
    }),
  ];
}

// ── ASSEMBLE ─────────────────────────────────────────────────────────

async function main() {
  const doc = new Document({
    styles: {
      default: { document: { run: { font: "Arial", size: 20 } } },
    },
    sections: [{
      properties: {
        page: {
          size: { width: 12240, height: 15840 },
          margin: { top: 720, right: 1080, bottom: 720, left: 1080 }
        }
      },
      children: [
        headerBanner(),
        ...whyThisMakesSense(),
        ...whereWeSeeTheFit(),
        ...whatThisCouldLookLike(),
        ...biggerPicture(),
        ...ctaFooter(),
      ]
    }]
  });

  const buf = await Packer.toBuffer(doc);
  fs.writeFileSync("/home/claude/luxora_x_beam_wellness.docx", buf);
  console.log("Done.");
}

main().catch(console.error);

